static void change(StringBuilder sb, String s) {
    sb.append("!");
    s = s + "!";
    sb = new StringBuilder("new");
}

public static void main(String[] args) {
    StringBuilder sb = new StringBuilder("hi");
    String s = "hi";
    change(sb, s);
    System.out.println(sb + " " + s);
}
